declare(strict_types=1); require __DIR__.'/includes/bootstrap.php'; require_role('admin','manager','leader','student'); $u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf(); $a=$_POST['action']??'';
 try{
  if($a==='partner'&&has_role('admin','manager')){$email=post_str('contact_email',150); if(post_str('name')===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))) throw new RuntimeException('Escribe el nombre y un correo válido.'); query('INSERT INTO partners(name,sector,contact_name,contact_email,status) VALUES(?,?,?,?,?)',[post_str('name',180),post_str('sector',120),post_str('contact_name',150),$email,allowed_value($_POST['status']??'',['prospect','active','inactive'],'prospect')]);audit('create','partner',(int)db()->lastInsertId(),$_POST['name']);flash('success','Aliado registrado.');}
  elseif($a==='agreement'&&has_role('admin','manager')){if(post_str('title')===''||post_str('objective')==='') throw new RuntimeException('Escribe el nombre y el objeto del convenio.'); query('INSERT INTO agreements(partner_id,title,objective,responsible_id,starts_on,ends_on,status,evidence_reference) VALUES(?,?,?,?,?,?,?,?)',[(int)$_POST['partner_id'],post_str('title',180),post_str('objective'),(int)$_POST['responsible_id'],valid_date($_POST['starts_on']??null),valid_date($_POST['ends_on']??null),allowed_value($_POST['status']??'',['proposed','active','expired','closed'],'proposed'),post_str('evidence_reference',255)]); notify((int)$_POST['responsible_id'],'Eres responsable de un convenio',post_str('title',180),'alliances.php');audit('create','agreement',(int)db()->lastInsertId(),$_POST['title']);flash('success','Convenio registrado.');}
  elseif($a==='agreement_status'&&has_role('admin','manager')){$st=allowed_value($_POST['status']??'',['proposed','active','expired','closed'],'proposed');query('UPDATE agreements SET status=? WHERE id=?',[$st,(int)$_POST['id']]);audit('status','agreement',(int)$_POST['id'],$st);flash('success','Estado del convenio actualizado.');}
  elseif($a==='activity'&&has_role('admin','manager','leader')){$d=valid_date($_POST['occurs_on']??null); if(post_str('title')===''||!$d) throw new RuntimeException('Escribe la actividad y su fecha.'); query('INSERT INTO activities(agreement_id,title,occurs_on,status,result_summary) VALUES(?,?,?,?,?)',[(int)$_POST['agreement_id'],post_str('title',180),$d,allowed_value($_POST['status']??'',['planned','completed','cancelled'],'planned'),post_str('result_summary')]);audit('create','activity',(int)db()->lastInsertId());flash('success','Actividad agregada.');}
 }catch(Throwable $e){flash('error',$e instanceof RuntimeException?$e->getMessage():'No fue posible guardar el registro. Revisa los datos.');}redirect('alliances.php');
}
$partners=rows('SELECT * FROM partners ORDER BY name');$responsibles=rows("SELECT id,full_name FROM users WHERE role IN ('admin','manager','leader') AND status='active' ORDER BY full_name");
$agreements=rows('SELECT a.*,p.name partner,u.full_name responsible,(SELECT COUNT(*) FROM activities x WHERE x.agreement_id=a.id) activities FROM agreements a JOIN partners p ON p.id=a.partner_id JOIN users u ON u.id=a.responsible_id ORDER BY FIELD(a.status,"active","proposed","expired","closed"),a.ends_on');
$activities=rows('SELECT x.*,a.title agreement_title,p.name partner FROM activities x JOIN agreements a ON a.id=x.agreement_id JOIN partners p ON p.id=a.partner_id ORDER BY x.occurs_on DESC LIMIT 12');
app_header('Alianzas institucionales','ODS 17 · ALIANZAS PARA LOS OBJETIVOS');
?><div class="page-actions"><div><p>Relaciona aliados, convenios, responsables y resultados verificables.</p></div><?php if(has_role('admin','manager')):?><div class="button-row" id="tour-new-partner"><button class="button button-ghost" type="button" data-open="partner-form"><?= icon('building',16) ?>Nuevo aliado</button><button class="button button-primary" type="button" data-open="agreement-form"><?= icon('handshake',16) ?>Nuevo convenio</button></div><?php endif;?></div>
<?php if(has_role('admin','manager')):?><dialog id="partner-form"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="partner"><div class="modal-head"><h2>Registrar aliado</h2><button type="button" data-close>×</button></div><div class="form-grid"><label>Nombre<input name="name" required></label><label>Sector<input name="sector"></label><label>Contacto<input name="contact_name"></label><label>Correo<input type="email" name="contact_email"></label><label>Estado<select name="status"><option value="prospect">Prospecto</option><option value="active">Activo</option></select></label></div><div class="modal-actions"><button type="button" class="button button-ghost" data-close>Cancelar</button><button class="button button-primary">Guardar</button></div></form></dialog>
<dialog id="agreement-form"><form method="post" class="modal-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="agreement"><div class="modal-head"><h2>Registrar convenio</h2><button type="button" data-close>×</button></div><div class="form-grid"><label>Aliado<select name="partner_id" required><?php foreach($partners as $p):?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach;?></select></label><label>Responsable<select name="responsible_id"><?php foreach($responsibles as $r):?><option value="<?= $r['id'] ?>"><?= e($r['full_name']) ?></option><?php endforeach;?></select></label><label class="span-2">Nombre del convenio<input name="title" required></label><label>Inicio<input type="date" name="starts_on"></label><label>Fin<input type="date" name="ends_on"></label><label>Estado<select name="status"><option value="proposed">Propuesto</option><option value="active">Vigente</option><option value="expired">Vencido</option><option value="closed">Cerrado</option></select></label><label>Referencia de evidencia<input name="evidence_reference" placeholder="Código o ubicación"></label><label class="span-2">Objeto<textarea name="objective" required></textarea></label></div><div class="modal-actions"><button type="button" class="button button-ghost" data-close>Cancelar</button><button class="button button-primary">Guardar convenio</button></div></form></dialog><?php endif;?>
<section class="partner-strip" id="tour-partners"><?php if(!$partners):?><div class="empty panel">Aún no hay aliados registrados.</div><?php endif;?><?php foreach($partners as $p):?><article><span class="org-avatar small tone-ods17"><?= icon('building',18) ?></span><div><strong><?= e($p['name']) ?></strong><small><?= e($p['sector']?:'Sector por definir') ?></small></div><span class="status status-<?= e($p['status']) ?>"><?= e(status_label($p['status'])) ?></span></article><?php endforeach;?></section>
<section class="panel" id="tour-agreements"><div class="panel-head"><div><span class="eyebrow">CONVENIOS</span><h2>Seguimiento institucional</h2></div></div><div class="agreement-grid"><?php if(!$agreements):?><div class="empty">Aún no hay convenios.</div><?php endif;?><?php foreach($agreements as $a):?><article><div class="card-top"><span class="status status-<?= e($a['status']) ?>"><?= e(status_label($a['status'])) ?></span><span><?= icon('calendar',13) ?><?= (int)$a['activities'] ?> actividades</span></div><h3><?= e($a['title']) ?></h3><p class="organization"><?= e($a['partner']) ?></p><p><?= e($a['objective']) ?></p><dl><div><dt>Responsable</dt><dd><?= e($a['responsible']) ?></dd></div><div><dt>Vigencia</dt><dd><?= $a['starts_on']?e(date('d/m/Y',strtotime($a['starts_on']))):'—' ?> a <?= $a['ends_on']?e(date('d/m/Y',strtotime($a['ends_on']))):'—' ?></dd></div><div><dt>Evidencia</dt><dd><?= e($a['evidence_reference']?:'Pendiente') ?></dd></div></dl><?php if(has_role('admin','manager')):?><form method="post" class="inline-form agreement-status"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="agreement_status"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><select name="status" aria-label="Estado del convenio"><?php foreach(['proposed','active','expired','closed'] as $st):?><option value="<?= $st ?>" <?= $a['status']===$st?'selected':'' ?>><?= e($st==='active'?'Vigente':status_label($st)) ?></option><?php endforeach;?></select><button class="button button-small">Guardar</button></form><?php endif;?><?php if(has_role('admin','manager','leader')):?><details class="add-inline"><summary><?= icon('plus',14) ?>Registrar actividad</summary><form method="post" class="stack-form compact"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="activity"><input type="hidden" name="agreement_id" value="<?= $a['id'] ?>"><label>Actividad<input name="title" required></label><label>Fecha<input type="date" name="occurs_on" required></label><label>Estado<select name="status"><option value="planned">Planeada</option><option value="completed">Completada</option></select></label><label>Resultado<textarea name="result_summary"></textarea></label><button class="button button-small">Guardar actividad</button></form></details><?php endif;?></article><?php endforeach;?></div></section>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">ACTIVIDAD RECIENTE</span><h2>Resultados de colaboración</h2></div></div><div class="timeline"><?php if(!$activities):?><div class="empty">Sin actividades registradas. Agrega la primera desde un convenio.</div><?php endif;?><?php foreach($activities as $x):?><article><time><?= e(date('d M Y',strtotime($x['occurs_on']))) ?></time><span></span><div><strong><?= e($x['title']) ?></strong><small><?= e($x['partner']) ?> · <?= e($x['agreement_title']) ?></small><p><?= e($x['result_summary']?:'Resultado pendiente de registrar.') ?></p></div></article><?php endforeach;?></div></section><?php app_footer(); ?>
